from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='A comienzos del siglo XIII aparece en Castilla una poesía narrativa distinta de la de los juglares: la escriben clérigos, cuenta el número de sílabas y trata asuntos religiosos y morales. Este capítulo describe el mester de clerecía, su estrofa característica, la cuaderna vía, y la obra de su principal representante, Gonzalo de Berceo.',
        quotes=[Q('es_mester','El mester de clerecía es una literatura medieval compuesta por clérigos'), Q('en_mester','It was cultivated in the 13th century by Spanish learned poets, usually clerics')]))
    P.append(dict(text='La palabra mester procede del latín ministerium, «oficio», y las tres escuelas literarias medievales corresponden a los tres estamentos de la sociedad: el mester de juglaría, popular y recitado en plazas y castillos; el mester de cortesía, escrito en prosa en el ámbito de la corte, y el mester de clerecía, nacido en ambientes eclesiásticos cultos como los estudios generales y las escuelas catedralicias. Los clérigos que lo cultivaban no eran necesariamente sacerdotes: bastaba con haber cursado los estudios superiores de la época, de modo que podían ser nobles, judíos o incluso musulmanes.',
        quotes=[Q('es_mester','Mester viene del latín ministerium (oficio)','mesteres que emanaban de esos sectores de la sociedad'), Q('es_mester','es decir, hombres instruidos y no necesariamente sacerdotes'), Q('en_mester','It was cultivated in the 13th century by Spanish learned poets, usually clerics')]))
    P.append(dict(text='Frente al verso irregular y la rima asonante de los juglares, los poetas de clerecía escribieron en verso regular. Su estrofa es la cuaderna vía, un tetrástrofo monorrimo: cuatro versos alejandrinos de catorce sílabas, divididos en dos hemistiquios de siete separados por una cesura, que comparten una misma rima consonante. La consonante, más exigente que la asonante, exige que coincidan todos los sonidos desde la vocal tónica, y por eso la clerecía se presentaba a sí misma como un arte de poetas que contaban sílabas con cuidado y buscaban versos perfectos.',
        quotes=[Q('es_mester','Están escritas en verso regular, preferentemente alejandrino o de catorce sílabas','cesura'), Q('en_mester','These poets carefully counted the number of syllables in each line and strived to achieve perfect lines.')]))
    P.append(dict(text='La finalidad de esta poesía era a la vez estética y didáctica. Sus autores querían entretener, enseñar e impulsar a la virtud y a la piedad, y por eso tratan temas religiosos e historiográficos tomados casi siempre de obras latinas medievales. Dos rasgos separan la clerecía de la juglaría: el didactismo y la erudición. El vocabulario está lleno de cultismos, palabras tomadas directamente del latín, y los versos, aunque pensados para recitarse, expresan una conciencia clara de querer hacer «otra cosa» que los juglares.',
        quotes=[Q('es_mester','Se crean para entretener (delectare) y enseñar (docere) a la gente'), Q('en_mester','Two traits separate this form from the mester de juglaría: didacticism and erudition.')]))
    P.append(dict(text='Gonzalo de Berceo, nacido hacia 1196 en la aldea riojana de Berceo, junto al monasterio de San Millán de la Cogolla, es el principal representante de la escuela. Fue diácono en 1221 y presbítero en 1237, y se formó entre 1222 y 1227 en los estudios generales de Palencia, los primeros que hubo en España, con cátedras de teología, derecho canónico, lógica y artes. No fue fraile, como se suele creer, sino clérigo y notario eclesiástico de los monasterios de San Millán y de Santo Domingo de Silos. Murió hacia 1264.',
        quotes=[Q('es_berceo','se formó entre 1222 y 1227 en los recientemente creados estudios generales','de Palencia'), Q('en_berceo','Gonzalo is recorded as being a deacon in his home parish in the early 1220s, and as a priest from 1237 on.')]))
    P.append(dict(text='La obra de Berceo es toda religiosa. Se compone sobre todo de hagiografías, biografías de santos vinculados a los monasterios en que trabajó, como la Vida de San Millán de la Cogolla, la Vida de Santo Domingo de Silos y la Vida de Santa Oria, y de obras marianas y teológicas. Su título más conocido son los Milagros de Nuestra Señora, que comienzan con una introducción alegórica en un prado idealizado y siguen con veinticinco milagros realizados por la Virgen en favor de personas de distintos grupos sociales. Berceo no inventa los relatos: los traduce y amplifica a partir de textos latinos, y su originalidad está en el tratamiento, el estilo y los detalles costumbristas.',
        quotes=[Q('es_berceo','A continuación, se suceden veinticinco milagros realizados por la Virgen'), Q('en_berceo','He is celebrated for his poems on religious subjects, written in a style of verse which has been called Mester de Clerecía')]))
    P.append(dict(text='La crítica ha discutido los móviles de Berceo. Su cercanía a San Millán y sus hagiografías, que fomentaban la devoción, las peregrinaciones y las donaciones en torno a las reliquias del monasterio, han llevado a considerarlo un propagandista de los intereses de la abadía en un momento de decadencia. Otros críticos presentan al poeta como menos movido por esos intereses. Ambas lecturas coinciden en que la poesía de clerecía tenía una función práctica además de la literaria: llegar a un público de aldeanos que no leía latín.',
        quotes=[Q('es_berceo','el monasterio de San Millán atravesaba un periodo de decadencia','que celebra y que conservaba el monasterio'), Q('en_berceo','have led him to be considered a propagandist for the narrow interests of the monastery of San Millán')]))
    P.append(dict(text='El mester de clerecía evolucionó con la sociedad. En el siglo XIII predominan la monometría, el seguimiento estricto de las fuentes y los temas religiosos y morales. En el siglo XIV la cuaderna vía se flexibiliza con versos más largos, zéjeles y rimas internas, entran los temas profanos y el autor empieza a ser artista en lugar de artesano, como ocurre con Juan Ruiz en el Libro de buen amor. En el siglo XV, tras la peste negra y el cisma de Occidente, se vuelve a una religiosidad más sombría y a cuadernas vías de versos de dieciséis sílabas.',
        quotes=[Q('es_mester','La evolución temática y formal del mester de clerecía refleja la evolución de la sociedad de su tiempo'), Q('en_mester','Fourteenth-century poet Juan Ruíz, also known as the Arcipreste de Hita, used the cuaderna vía in parts of his famous work Libro de buen amor.')]))
    P.append(dict(role='definition', text='Cuaderna vía: estrofa característica del mester de clerecía, formada por cuatro versos alejandrinos de catorce sílabas, divididos en dos hemistiquios de siete, que comparten una misma rima consonante. También se llama tetrástrofo monorrimo.',
        quotes=[Q('es_mester','el tetrástrofo monorrimo'), Q('en_mester','The stanzas in them are composed of 4 alexandrine lines which contain 14 syllables each.')]))
    P.append(dict(role='consejo', text='Para reconocer un texto de clerecía, compruebe primero la regularidad: cuente los siete más siete sílabas de cada verso y verifique que los cuatro versos riman entre sí con rima consonante. Si encuentra versos de medida irregular y rima asonante, está ante la tradición juglaresca.',
        quotes=[Q('es_mester','Utilizan la rima más difícil y exigente, la consonante'), Q('en_mester','with consonantal rhyme in stanzas of four lines each')]))
    P.append(dict(role='self_check', text='¿Por qué Berceo no puede considerarse un fraile ni un autor plenamente original? ¿Qué rasgos métricos distinguen la cuaderna vía del verso del Cantar de mio Cid? ¿Qué cambios temáticos introduce el siglo XIV respecto del XIII?',
        quotes=[Q('es_berceo','No se muestra como un narrador original','amplificatio'), Q('en_mester','Unlike Mester de Juglaría, Mester de Clerecía was written on paper, not anonymous, with regular metre (the cuaderna vía)')]))
    return P

def _legacy_numeric_problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='Una cuaderna vía está formada por cuatro versos alejandrinos de catorce sílabas. Un poema hipotético en cuaderna vía tiene 120 estrofas. Calcule cuántos versos y cuántas sílabas métricas nominales contiene, y cuántas sílabas corresponden a cada hemistiquio de siete.',
        expected='6720', quotes=[Q('en_mester','The stanzas in them are composed of 4 alexandrine lines which contain 14 syllables each.'), Q('es_mester','el tetrástrofo monorrimo')],
        method='Producto de estrofas por versos por sílabas',
        solution=dict(given=[dict(symbol='E',value=120,unit='dimensionless',meaning='número de estrofas'),dict(symbol='v',value=4,unit='dimensionless',meaning='versos por estrofa'),dict(symbol='s',value=14,unit='dimensionless',meaning='sílabas por verso alejandrino')],
          unknown='El número de versos, el de sílabas nominales y las sílabas de cada hemistiquio.',
          model=[dict(name='Versos totales',latex='V = E\\,v',symbolic='E*v'),dict(name='Sílabas totales',latex='S = E\\,v\\,s',symbolic='E*v*s')],
          assumptions=['Se cuenta el número nominal de sílabas métricas; sinalefas, hiatos y licencias hacen que el cómputo real varíe en versos concretos.'],
          development=['Cada verso se divide en dos hemistiquios de siete sílabas separados por una cesura.'],
          steps=[dict(text='Versos del poema',equation='V = 120 \\cdot 4',expression='120*4',expected=480,unit='dimensionless'),
                 dict(text='Sílabas nominales',equation='S = 480 \\cdot 14',expression='480*14',expected=6720,unit='dimensionless'),
                 dict(text='Sílabas por hemistiquio',equation='h = 14/2',expression='14/2',expected=7,unit='dimensionless')],
          result='El poema tiene 480 versos y 6720 sílabas nominales; cada hemistiquio tiene 7.',
          interpretation='La regularidad de la cuaderna vía permite calcular la extensión de un poema contando solo estrofas, algo imposible en el verso irregular del Cantar.',
          limitations=['El cómputo es nominal: la sinalefa y la diéresis modifican el número real de sílabas métricas.'],
          mistakes=['Contar solo versos y olvidar que cada verso tiene catorce sílabas.']))]


