HEADS = {1: 'El nombre «clerecía»', 2: 'Un verso medido', 3: 'Para qué se escribía', 4: 'Berceo, un clérigo riojano', 5: 'Las obras de Berceo', 6: 'Los móviles de Berceo', 7: 'La cuaderna vía cambia'}


def extend(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(text='La estrofa que se presenta a sí misma\nLa denominación de este arte nace de un verso. El Libro de Alexandre, primera obra castellana en cuaderna vía, dice en su segunda estrofa: «Mester traygo fermoso, non es de joglaria / mester es sen pecado, ca es de clerecía / fablar curso rimado por la cuaderna vía / a síllabas cuntadas, ca es grant maestría». En cuatro versos el autor define su programa: un oficio sin pecado, propio de clérigos, que se hace con rima y con las sílabas contadas. De esa misma estrofa proceden los nombres «mester de clerecía» y «cuaderna vía». Es un caso poco común de poética explícita en la Edad Media, y permite a la crítica definir la clerecía con las propias palabras de sus autores.',
        quotes=[Q('es_cuaderna', 'Mester traygo fermoso, non es de joglaria'), Q('es_cuaderna', 'a síllabas cuntadas, ca es grant maestría.'), Q('es_cuaderna', 'De la misma estrofa procede también la denominación "Mester de clerecía".'), Q('en_mester', 'These poets carefully counted the number of syllables in each line')]))
    P.append(dict(text='Cuatro caminos\nEl nombre «cuaderna vía» alude al quadrivium, las cuatro ciencias que formaban los altos estudios de la Edad Media, por oposición al trivium de gramática, retórica y dialéctica. Los clérigos que escribían en cuaderna vía habían cursado esos estudios, y por eso la estrofa se asocia con la poesía culta. La fuente señala que la primera obra en castellano que usa esta estrofa es el anónimo Libro de Alexandre. La fuente en inglés lo resume al contraponer los dos mesteres: la clerecía se escribe, no es anónima, tiene métrica regular y la hacen autores instruidos; los temas son más serios, religiosos, históricos y novelescos.',
        quotes=[Q('es_cuaderna', 'Su nombre proviene del quadrivium'), Q('es_cuaderna', 'Los clérigos o sabios que escribían en cuaderna vía habían cursado los altos estudios de entonces'), Q('es_cuaderna', 'La primera obra en castellano que utiliza la cuaderna vía es el anónimo Libro de Alexandre'), Q('en_mester', 'Unlike Mester de Juglaría, Mester de Clerecía was written on paper, not anonymous, with regular metre (the cuaderna vía) and done by educated authors.')]))
    P.append(dict(text='De dónde viene el verso\nLa cuaderna vía se llama también tetrástrofo monorrimo: son cuatro versos alejandrinos, de catorce sílabas, con una sola rima consonante, y cada verso se divide en dos hemistiquios de siete sílabas. Según Alan Deyermond es una adaptación del alejandrino francés; otros críticos han señalado la influencia de la poesía latina francesa del siglo XII, y Menéndez Pelayo la relaciona con la estrofa de la poesía latina goliardesca. Lo que sabemos es que la cuarteta monorrima de alejandrinos era conocida en la Romania desde mediados del siglo XII, y que su llegada a Castilla se atribuye al influjo francés sobre los Estudios Generales de Palencia, la primera universidad castellana, en la que estudió Berceo.',
        quotes=[Q('es_cuaderna', 'se compone de cuatro versos alejandrinos, es decir, de catorce sílabas, con rima consonante uniforme (monorrimo)'), Q('es_cuaderna', 'la cuaderna vía es una adaptación del alejandrino francés'), Q('es_cuaderna', 'era una estrofa conocida a lo largo de la Romania desde mediados del siglo XII'), Q('es_cuaderna', 'Probablemente se debe al influjo francés ejercido sobre los Estudios Generales de Palencia'), Q('en_alexandrine', 'The Spanish verso alejandrino is a line of 7+7 syllables, probably developed in imitation of the French alexandrine.')]))
    P.append(dict(text='El Libro de Alexandre\nEl Libro de Alexandre cuenta con muchos elementos fabulosos la vida de Alejandro Magno en 2669 estrofas y 10 700 versos, según la fuente en español (2675 estrofas en la inglesa). Sigue sobre todo la Alexandreis, poema latino de Gautier de Châtillon, pero la altera y añade otras fuentes, entre ellas la Historia de preliis y un poema francés del siglo XII. El manejo de las fuentes es mucho más elaborado que en otros poemas clericales, como los de Berceo. La obra es anónima: una copia la atribuye a Berceo, otra a Juan Lorenzo de Astorga, pero hoy la crítica no admite ninguna de las dos. Su fecha es discutida: el mayor consenso la sitúa hacia 1230, mientras que Marcos Marín, a partir de la estrofa 1799, propone entre 1202 y 1207, lo que excluye a Berceo, que no tendría más de nueve años.',
        quotes=[Q('es_alexandre', 'Se compone de 2669 estrofas y 10 700 versos.'), Q('en_alexandre', 'It consists of 2,675 stanzas of cuaderna vía and 10,700 lines.'), Q('es_alexandre', 'Utiliza fundamentalmente el Alexandreis de Gautier de Châtillon'), Q('es_alexandre', 'Actualmente la crítica considera que ni Juan Lorenzo ni el autor de los Milagros de Nuestra Señora fueron los autores del Alexandre, por lo que la obra se considera anónima.'), Q('es_alexandre', 'Francisco Marcos Marín, a partir del propio texto (estrofa 1799) concluye que la fecha de composición debió ser entre 1202 y 1207')]))
    P.append(dict(text='Apolonio y Fernán González\nOtras dos obras muestran hasta dónde llegó el género. El Libro de Apolonio, hacia mediados del siglo XIII, cuenta las aventuras de un rey que tras una deshonra se embarca y sufre desgracias, con un propósito moralizante según los valores cristianos: el que mantiene su fe es recompensado. Su autor es desconocido, aunque se observan rasgos aragoneses. El Poema de Fernán González es una refundición en cuaderna vía de un cantar de gesta sobre el conde de Castilla, y la fuente inglesa lo fecha entre 1250 y 1266 y lo atribuye a un monje de San Pedro de Arlanza, donde estaba enterrado el conde. Aquí la clerecía toma el tema de la épica, el héroe castellano, y lo pasa por la forma culta, un buen ejemplo del contraste que se estudió en el capítulo anterior.',
        quotes=[Q('es_apolonio', 'dan lugar a un escrito con un propósito moralizante según los valores cristianos'), Q('es_apolonio', 'una opinión más generalizada que postula la fecha de composición en 1250'), Q('es_fernan', 'El Poema de Fernán González es un poema épico del mester de clerecía cuyo contenido es el de un cantar de gesta'), Q('en_fernan', 'It was written between 1250 and 1266 by a monk of San Pedro de Arlanza.'), Q('es_cuaderna', 'Poema de Fernán González, refundición en cuaderna vía de un cantar de gesta')]))
    P.append(dict(text='Un clérigo de San Millán\nGonzalo de Berceo nació hacia 1196 en la aldea riojana de Berceo y se educó en el monasterio de San Millán de la Cogolla, a cuya órbita perteneció toda su vida ({{fig:suso}}). Fue primero diácono, en 1221, y después presbítero, en 1237, y los documentos lo muestran como notario del abad Juan Sánchez. La fuente inglesa añade que pudo estudiar en la naciente universidad de Palencia y que escribió en dialecto riojano antiguo. Su situación importa para entender su obra: es un clérigo secular que escribe para un monasterio y para los fieles que lo visitan, y por eso la fuente española dice que llegó a falsificar documentos para que los campesinos pagaran sus contribuciones al monasterio.',
        quotes=[Q('es_berceo', 'trabajó primero como diácono (1221) y luego como preste o presbítero (1237)'), Q('en_berceo', 'Gonzalo is recorded as being a deacon in his home parish in the early 1220s, and as a priest from 1237 on.'), Q('es_berceo', 'llegó incluso a falsificar documentos para conseguir que los reacios campesinos pagaran sus contribuciones al mismo'), Q('en_berceo', 'Berceo wrote in the Old Riojan dialect.')]))
    P.append(dict(text='Doce obras en tres grupos\nSe han conservado doce obras de Berceo en copias del siglo XVIII de dos códices, uno desaparecido de hacia 1260 y otro desmembrado de hacia 1325, que a su vez copiaban un original perdido. Se agrupan en obras sobre la Virgen María (Loores, Duelo y Milagros de Nuestra Señora), vidas de santos (San Millán, Santo Domingo de Silos, Santa Oria y San Lorenzo) y obras doctrinales (los Signos del Juicio Final y el Sacrificio de la misa), más tres himnos. La fuente inglesa los divide en devocionales, a su vez marianos y hagiográficos, y teológicos. En todos los casos los temas son religiosos y el procedimiento es el mismo: Berceo traduce, amplía y adapta obras latinas anteriores (amplificatio).',
        quotes=[Q('es_berceo', 'Se nos han conservado sus doce obras a través de copias dieciochescas de dos códices'), Q('es_berceo', 'Obras sobre la Virgen María: Loores de Nuestra Señora, Duelo que fizo la Virgen y Milagros de Nuestra Señora.'), Q('es_berceo', 'ya que traduce ampliando obras escritas anteriormente en latín (amplificatio)'), Q('en_berceo', 'The theological works are the Del sacrificio de la misa')]))
    P.append(dict(text='Una obra para el monasterio\nLa fuente inglesa recuerda que la cercanía de Berceo a San Millán y sus hagiografías, que parecen defender los intereses del monasterio, han llevado a considerarlo un propagandista de los intereses estrechos de San Millán, tesis defendida sobre todo por Brian Dutton; otros críticos, como Fernando Baños e Isabel Uría, lo presentan menos movido por esos intereses. Los Milagros muestran la misma tensión. La fuente española dice que se escribieron con un fin de entretenimiento, de enseñanza religiosa y de dar a conocer el monasterio de San Millán, y que su propósito es mariano: rendir culto a la Virgen, posiblemente Nuestra Señora de Marzo, venerada en el altar mayor de San Millán de Suso. No son móviles incompatibles: el culto y la promoción del monasterio podían ir juntos.',
        quotes=[Q('en_berceo', 'have led him to be considered a propagandist for the narrow interests of the monastery of San Millán'), Q('es_milagros', 'con un fin de entretenimiento, de enseñanza religiosa y de dar a conocer el monasterio de San Millán de la Cogolla'), Q('es_milagros', 'El propósito de la obra es claramente mariano: rendir culto a la Virgen')]))
    P.append(dict(text='Cómo están hechos los Milagros\nLos Milagros de Nuestra Señora, escritos entre 1246 y 1252 aproximadamente, relatan 25 milagros de la Virgen. El número no es casual: la fuente señala una estructura simbólica en torno al cinco, cifra de la Virgen según la numerología cristiana, de modo que 5 por 5 son 25. El manuscrito latino que usó Berceo contenía 28; el poeta seleccionó 24 y añadió uno de tradición local, el de la iglesia robada. Todos siguen la misma estructura de caída y redención: una persona devota de la Virgen está en peligro y se salva gracias a un milagro. A veces hay exordio, siempre una narración y casi siempre una moraleja final que enseña las ventajas de ser devoto.',
        quotes=[Q('es_milagros', 'relatan 25 milagros de la Virgen María'), Q('es_milagros', 'El manuscrito que utilizó Berceo tenía 28, de los que seleccionó 24 y el poeta añadió uno de tradición local'), Q('es_milagros', 'Los milagros siguen todos la misma estructura de caída y redención'), Q('es_berceo', 'Al final de cada relato aparece una moraleja o enseñanza para hacer comprender al oyente las ventajas que reporta ser un devoto de la Virgen')]))
    P.append(dict(text='El prólogo: un prado alegórico\nLos Milagros se abren con una introducción alegórica en la que el poeta se presenta a sí mismo en una naturaleza idealizada. «Yo maestro Gonzalvo de Berçeo nonnado, / iendo en romeria caeçi en un prado»: un peregrino cansado llega a un prado verde, lleno de flores, árboles frutales, fuentes y aves, que parece «egual de paraiso». Después Berceo explica su sentido: «tolgamos la corteza, al meollo entremos», es decir, hay que quitar la cáscara y buscar el significado interior. Todos somos romeros en este mundo, y el prado es la Virgen, siempre verde porque nunca tuvo mácula su virginidad ({{fig:prado-alegoria}}). Las cuatro fuentes son los cuatro evangelios; los árboles que dan sombra, los santos milagros; las aves que cantan, los Padres como Agustín y Gregorio; y las flores, los nombres que se dan a María.',
        quotes=[Q('ws_prologo', 'Yo maestro Gonzalvo de Berçeo nonnado', 'caeçi en un prado'), Q('ws_prologo', 'Semeia esti prado egual de paraiso'), Q('ws_prologo', 'Tolgamos la corteza, al meollo entremos'), Q('ws_prologo', 'Todos somos romeos que camino andamos'), Q('ws_prologo', 'Los quatro evangelios esso significaban'), Q('es_milagros', 'La obra comienza con una introducción alegórica en la que el autor se presenta a sí mismo en una naturaleza idealizada')]))
    P.append(dict(text='Un milagro: la casulla de San Ildefonso\nEl primer milagro cuenta que san Ildefonso, arzobispo de Toledo, escribió un libro sobre la virginidad de María y estableció una fiesta en diciembre, y que la Virgen se le apareció con un libro en la mano y le regaló una casulla tejida por los ángeles para que la usara solo él. Su sucesor, el arzobispo Siagrio, soberbio y de seso liviano, quiso igualarse a Ildefonso, se sentó en su cátedra y se puso la casulla, pero esta le quedó tan estrecha que lo ahogó. Es un milagro de los que premian o castigan, y sirve de modelo de los demás: la devoción tiene premio y la soberbia castigo. La moraleja es explícita: «Si a ella sirvieremos nuestra pro buscaremos» y por poco servicio se recibe gran galardón.',
        quotes=[Q('ws_milagro1', 'Fizo della un libro de dichos colorados'), Q('ws_milagro1', 'Dioli una casulla sin aguida cosida'), Q('ws_milagro1', 'Alzaron arzobispo un calonge lozano', 'Era muy soberbio e de seso liviano'), Q('ws_milagro1', 'Por pocco de serviçio grant galardon prendremos.'), Q('es_berceo', 'En los que María premia o castiga a los hombres, como "La casulla de San Ildefonso".')]))
    P.append(dict(text='La lengua de Berceo\nLa originalidad de Berceo, según la fuente española, consiste en traducir al romance castellano y versificar textos latinos, acercando así a un registro popular el original clerical. Para ello usa recursos propios de los juglares, como el estilo directo y las apelaciones al público, y se permite introducir términos coloquiales o vulgarismos, porque era un hombre con estudios que podía usar tanto un lenguaje culto como uno vulgar. Su dialecto es el riojano, con cultismos tomados del latín y con vasquismos: aparecen palabras como beldur, «miedo», en «don Bildur» para designar al diablo. La combinación de latinismos, giros populares y humor es una parte esencial del encanto de los Milagros.',
        quotes=[Q('es_milagros', 'La originalidad de Berceo consiste en traducir al romance peninsular castellano, versificándolos, los textos latinos'), Q('es_milagros', 'hacer un uso abundante del estilo directo'), Q('es_milagros', 'por ello, se permite a sí mismo poder introducir términos coloquiales o vulgarismos'), Q('es_berceo', 'se caracterizan por la abundancia de vasquismos'), Q('es_berceo', 'Depuró el idioma castellano, en su variedad dialectal riojana')]))
    P.append(dict(text='Fechar los Milagros\nEl método para fechar la obra es el de las alusiones internas. En la estrofa 325 se menciona al obispo don Tello, que murió en 1247, de lo que se deduce que el «Milagro XIV» es anterior a esa fecha. En la estrofa 869, Berceo habla de Fernando III como ya fallecido, lo que lleva a 1252; el último milagro, el de la iglesia robada, debió escribirse durante el reinado de Alfonso X. De ahí que la obra se date entre 1246 y 1252 aproximadamente, y que se piense en una elaboración larga. La tradición textual es frágil: del manuscrito original se hicieron dos copias y de ellas derivan las que hoy se conocen; una del siglo XIV, redescubierta entre 1926 y 1974.',
        quotes=[Q('es_milagros', 'por una alusión al obispo don Tello (a. 1207-1247) en la estrofa 325'), Q('es_milagros', 'en la estrofa 869 Berceo se refiere a Fernando III como ya fallecido (1252)'), Q('es_milagros', 'escrita entre 1246 y 1252 aproximadamente'), Q('es_berceo', 'uno desaparecido de hacia 1260, y otro desmembrado de hacia 1325')]))
    P.append(dict(text='Los Milagros y la devoción mariana\nLas colecciones de milagros marianos aparecen en el siglo XI y se multiplican en los siglos XII y XIII, con autores especializados como Gautier de Coincy o Alfonso X el Sabio. Las hay locales, vinculadas a los centros de peregrinación, y generales; Berceo aprovechó una colección general en un periodo de divulgación de las lenguas románicas y de difusión de las tradiciones marianas. La fuente inglesa señala que los Milagros pudieron estar influidos por Gautier de Coincy. Dentro de la obra, la Virgen aparece idealizada frente a los santos, porque en los siglos XI y XII se había consolidado su figura; y el mundo se divide en un plano sobrenatural, con cielo, purgatorio e infierno, y otro terrenal en el que ocurren los pecados y se piden los milagros.',
        quotes=[Q('es_milagros', 'Las colecciones de milagros marianos aparecieron a lo largo del siglo XI'), Q('es_milagros', 'Berceo aprovechó una de estas colecciones de milagros generales para componer la suya'), Q('en_berceo', 'perhaps influenced by Gautier de Coincy'), Q('es_milagros', 'En los milagros, aparece el mundo sobrenatural, ya que aparece el purgatorio, el cielo y el infierno.')]))
    P.append(dict(text='Poesía de clérigos, poesía de juglares\nLa distinción entre mesteres es más clara en la teoría que en la práctica. El poeta de clerecía presume de contar las sílabas y de trabajar con fuentes escritas, pero Berceo usa fórmulas y apelaciones al público propias de los juglares, y se ha llegado a llamarlo «juglar de Dios». La diferencia métrica, en cambio, es fácil de comprobar: mientras el Cantar de mio Cid usa versos irregulares, de 14 a 16 sílabas en su mayoría y rima asonante, la cuaderna vía exige catorce sílabas, hemistiquio de siete y rima consonante única en cada estrofa. Al comienzo todo esto se cumple: la fuente señala que en las obras producidas entre 1225 y 1265 la cuaderna vía mantiene su regularidad métrica.',
        quotes=[Q('es_cuaderna', 'En las primeras obras del Mester de clerecía, aquellas producidas entre 1225 y 1265, la cuaderna vía mantiene su regularidad métrica.'), Q('es_gesta', 'Versos irregulares, mayoritariamente entre [14] y [16] sílabas, divididos en dos hemistiquios y con rima asonante'), Q('es_berceo', 'recurrió a fórmulas de la literatura oral tradicional y del mester de juglaría'), Q('es_milagros', 'dar ciertas pinceladas humorísticas a lo narrado')]))
    P.append(dict(text='La cuaderna vía se relaja\nEn el siglo XIV la regularidad se pierde. Las irregularidades afectan a la rima y al cómputo silábico, se tiende al hemistiquio de ocho sílabas, que da versos de dieciséis, y se admite la sinalefa, con lo que el ritmo se hace más fluido. El Libro de buen amor, de Juan Ruiz, está compuesto en un ochenta por ciento en cuaderna vía, aunque sustituye a menudo la consonancia por la asonancia y los alejandrinos por versos de dieciséis sílabas. El Libro de miseria de omne hace lo mismo con el alejandrino. La estrofa llegó incluso al epitafio del obispo Sancho de Ávila, hacia 1332. La evolución explica por qué las dos primeras generaciones de poetas parecen más lejanas en la forma que en la intención.',
        quotes=[Q('es_cuaderna', 'se admite la sinalefa, la cual repercute en el nivel rítmico y lingüístico ya que el ritmo se hace más fluido'), Q('es_cuaderna', 'El Libro de Buen Amor está compuesto en un ochenta por ciento en cuaderna vía'), Q('es_cuaderna', 'En el Libro de miseria de omne se sustituye el alejandrino por el verso de dieciséis sílabas.'), Q('es_mester', 'al contrario que el mester de juglaría, que utiliza versos irregulares y anisosilábicos')]))
    return P


